# Degeneracy 13.0% for Few-NERD 8B FT
for k in sorted(experiments.keys()):
    if 'fewnerd' in k.lower():
        m = experiments[k].get('metrics', {})
        if not m:
            continue
        ms = json.dumps(m)
        def find_degen(d, path=''):
            if isinstance(d, (int, float)):
                if (12.5 <= d <= 13.5) or (0.125 <= d <= 0.135):
                    print(f'  {k}{path} = {d}')
            elif isinstance(d, dict):
                for dk, dv in d.items():
                    find_degen(dv, f'.{dk}')
        find_degen(m)

print()
print('=== FewNERD mf4_v2 degeneracy ===')
for k in ['exp_fewnerd_mf4_v2_s42', 'exp_fewnerd_mf4_v2_s123', 'exp_fewnerd_mf4v2_s456']:
    m = experiments[k].get('metrics', {})
    for mk, mv in m.items():
        if 'degen' in mk.lower():
            print(f'  {k}.{mk} = {mv}')

print()
