# But exp_021 reports degeneracy_rate=0.101 (10.1%)
# And the table says 13.0%
# It seems the degen in the table uses a different definition

# Let me check 'constant_f1' degeneracy in FewNERD experiments  
for k in sorted(experiments.keys()):
    if 'fewnerd' in k.lower() and 'mf4' in k.lower():
        m = experiments[k].get('metrics', {})
        for mk, mv in m.items():
            if 'degen' in mk.lower() or 'sample_f1_pct_zero' in mk.lower():
